/// <summary>Consumer side of the .NET ↔ Python contract: the fixtures are generated by the Python service (scripts/export_contract.py).</summary>
public class AiContractTests
{
    private static readonly string Contracts = FindContracts();

    private static string FindContracts()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            var candidate = Path.Combine(dir.FullName, "contracts");
            if (File.Exists(Path.Combine(candidate, "ai-service.openapi.json")))
            {
                return candidate;
            }
        }

        throw new InvalidOperationException("contracts/ directory not found");
    }

    private static string Fixture(string name) => File.ReadAllText(Path.Combine(Contracts, "fixtures", name));

    private static AiServiceClient ClientReturning(HttpStatusCode status, string body, Action<HttpRequestMessage>? inspect = null, string? retryAfter = null)
    {
        var handler = new StubHandler(request =>
        {
            inspect?.Invoke(request);
            var response = new HttpResponseMessage(status) { Content = new StringContent(body, Encoding.UTF8, "application/json") };
            if (retryAfter is not null)
            {
                response.Headers.Add("Retry-After", retryAfter);
            }

            return response;
        });
        return new AiServiceClient(new HttpClient(handler) { BaseAddress = new Uri("http://ai.test") }, NullLogger<AiServiceClient>.Instance);
    }

    [Fact]
    public async Task Analysis_fixture_deserializes_into_backend_dto()
    {
        string? sentBody = null;
        var client = ClientReturning(HttpStatusCode.OK, Fixture("analysis-response.json"),
            r => sentBody = r.Content!.ReadAsStringAsync().GetAwaiter().GetResult());
        var request = JsonSerializer.Deserialize<AiAnalysisRequest>(Fixture("analysis-request.json"), AiServiceClient.Json)!;

        var result = await client.AnalyzeAsync(request, CancellationToken.None);

        Assert.Equal("heuristic", result.Provider);
        Assert.Equal("network", result.Classification.Category);
        Assert.NotEmpty(result.Facts);
        Assert.NotEmpty(result.Recommendations);
        Assert.All(result.Hypotheses, h => Assert.InRange(h.Confidence ?? 0, 0, 1));

        // The request we serialize uses exactly the field names the Python schema expects.
        using var sent = JsonDocument.Parse(sentBody!);
        Assert.Equal(["requestId", "kind", "content", "context", "language"], sent.RootElement.EnumerateObject().Select(p => p.Name));
        Assert.True(sent.RootElement.GetProperty("context").TryGetProperty("pipelineName", out _));
    }

    [Fact]
    public async Task Assistant_and_activity_fixtures_deserialize()
    {
        var assistant = await ClientReturning(HttpStatusCode.OK, Fixture("assistant-response.json"))
            .AnswerAsync(JsonSerializer.Deserialize<AiAssistantRequest>(Fixture("assistant-request.json"), AiServiceClient.Json)!, CancellationToken.None);
        Assert.True(assistant.Grounded);
        Assert.Equal("inc-1", Assert.Single(assistant.Citations).Id);

        var activity = await ClientReturning(HttpStatusCode.OK, Fixture("activity-response.json"))
            .SummarizeActivityAsync(JsonSerializer.Deserialize<AiActivitySummaryRequest>(Fixture("activity-request.json"), AiServiceClient.Json)!, CancellationToken.None);
        Assert.NotEmpty(activity.Summary);
        Assert.NotEmpty(activity.Risks);
    }

    [Fact]
    public async Task Error_fixture_maps_to_ai_service_exception()
    {
        var client = ClientReturning(HttpStatusCode.Unauthorized, Fixture("error-response.json"));
        var ex = await Assert.ThrowsAsync<AiServiceException>(() =>
            client.AnalyzeAsync(new AiAnalysisRequest("r", "log_analysis", "x", new AiAnalysisContext(null, null, null, null, null)), CancellationToken.None));
        Assert.Equal("unauthorized", ex.Code);
        Assert.Equal(503, ex.StatusCode);
    }

    [Fact]
    public async Task Rate_limit_and_timeout_map_to_retryable_errors()
    {
        var limited = ClientReturning(HttpStatusCode.ServiceUnavailable,
            """{"error":{"code":"provider_rate_limited","message":"slow down","retryAfterSeconds":30}}""", retryAfter: "30");
        var ex = await Assert.ThrowsAsync<AiServiceException>(() =>
            limited.AnalyzeAsync(new AiAnalysisRequest("r", "log_analysis", "x", new AiAnalysisContext(null, null, null, null, null)), CancellationToken.None));
        Assert.Equal(("provider_rate_limited", 503, TimeSpan.FromSeconds(30)), (ex.Code, ex.StatusCode, ex.RetryAfter));

        var unreachable = new AiServiceClient(new HttpClient(new StubHandler(_ => throw new HttpRequestException("refused"))) { BaseAddress = new Uri("http://ai.test") },
            NullLogger<AiServiceClient>.Instance);
        var down = await Assert.ThrowsAsync<AiServiceException>(() =>
            unreachable.AnalyzeAsync(new AiAnalysisRequest("r", "log_analysis", "x", new AiAnalysisContext(null, null, null, null, null)), CancellationToken.None));
        Assert.Equal("ai_service_unreachable", down.Code);
        Assert.Null(await unreachable.GetHealthAsync(CancellationToken.None));
    }

    [Fact]
    public void Openapi_contract_declares_the_endpoints_the_backend_calls()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(Contracts, "ai-service.openapi.json")));
        var paths = doc.RootElement.GetProperty("paths").EnumerateObject().Select(p => p.Name).ToList();
        Assert.Contains("/v1/analyses", paths);
        Assert.Contains("/v1/assistant/answers", paths);
        Assert.Contains("/v1/summaries/activity", paths);
        Assert.Contains("/health/ready", paths);
    }

    private sealed class StubHandler(Func<HttpRequestMessage, HttpResponseMessage> respond) : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken) =>
            Task.FromResult(respond(request));
    }
}

public class SecurityPrimitivesTests
{
    private static AesGcmSecretProtector Protector(string keyId = "k1", Dictionary<string, string>? previous = null, byte seed = 1) =>
        new(Options.Create(new SecretsOptions
        {
            EncryptionKey = Convert.ToBase64String(Enumerable.Repeat(seed, 32).ToArray()),
            KeyId = keyId,
            PreviousKeys = previous ?? [],
        }));

    [Fact]
    public void Aes_gcm_round_trips_and_detects_tampering()
    {
        var protector = Protector();
        var protectedValue = protector.Protect("webhook-secret");
        Assert.StartsWith("k1:", protectedValue, StringComparison.Ordinal);
        Assert.NotEqual(protectedValue, protector.Protect("webhook-secret")); // random nonce
        Assert.Equal("webhook-secret", protector.Unprotect(protectedValue));

        var bytes = Convert.FromBase64String(protectedValue[3..]);
        bytes[^1] ^= 0xFF;
        Assert.ThrowsAny<CryptographicException>(() => protector.Unprotect("k1:" + Convert.ToBase64String(bytes)));
        Assert.Throws<CryptographicException>(() => Protector(seed: 2).Unprotect(protectedValue.Replace("k1:", "kx:", StringComparison.Ordinal)));
    }

    [Fact]
    public void Key_rotation_keeps_old_ciphertexts_readable()
    {
        var old = Protector("k1", seed: 1).Protect("legacy");
        var rotated = Protector("k2", new Dictionary<string, string> { ["k1"] = Convert.ToBase64String(Enumerable.Repeat((byte)1, 32).ToArray()) }, seed: 2);
        Assert.Equal("legacy", rotated.Unprotect(old));
        Assert.StartsWith("k2:", rotated.Protect("new"), StringComparison.Ordinal);
    }

    [Fact]
    public void Missing_or_short_key_fails_fast() =>
        Assert.Throws<InvalidOperationException>(() => new AesGcmSecretProtector(Options.Create(new SecretsOptions { EncryptionKey = Convert.ToBase64String(new byte[16]) })));

    [Theory]
    [InlineData(null, false)]
    [InlineData("", false)]
    [InlineData("sha1=abc", false)]
    [InlineData("sha256=nothex", false)]
    public void Webhook_signature_rejects_malformed_headers(string? header, bool expected) =>
        Assert.Equal(expected, WebhookReceiver.VerifySignature("secret", "{}"u8.ToArray(), header));

    [Fact]
    public void Webhook_signature_matches_github_algorithm()
    {
        var body = """{"zen":"Design for failure."}"""u8.ToArray();
        var signature = "sha256=" + Convert.ToHexStringLower(HMACSHA256.HashData("s3cret"u8.ToArray(), body));
        Assert.True(WebhookReceiver.VerifySignature("s3cret", body, signature));
        Assert.False(WebhookReceiver.VerifySignature("other", body, signature));
        body[0] = (byte)'[';
        Assert.False(WebhookReceiver.VerifySignature("s3cret", body, signature));
    }

    [Fact]
    public void Log_fingerprint_ignores_volatile_values()
    {
        Assert.Equal(IngestService.Fingerprint("Order 123 failed after 30 ms", null), IngestService.Fingerprint("Order 98765 failed after 4 ms", null));
        Assert.NotEqual(IngestService.Fingerprint("Order 1 failed", "System.TimeoutException: x"), IngestService.Fingerprint("Order 1 failed", "System.IO.IOException: x"));
    }

    [Fact]
    public void Repository_urls_only_allow_https()
    {
        Assert.Equal("https://github.com/acme/x", Repository.SafeUrl("https://github.com/acme/x"));
        Assert.Null(Repository.SafeUrl("javascript:alert(1)"));
        Assert.Null(Repository.SafeUrl("http://insecure.example"));
        Assert.Null(Repository.SafeUrl("not a url"));
    }
}

public class OperationsDomainTests
{
    private static readonly DateTimeOffset T0 = new(2026, 10, 11, 10, 0, 0, TimeSpan.Zero);

    private static PipelineRun NewRun()
    {
        var pipeline = new Pipeline(Guid.NewGuid(), EventSource.GitHub, "k", "CI", null, null, null, T0);
        return new PipelineRun(pipeline, "1", 1, 1, "main", "abc", "push", "octo", T0);
    }

    [Fact]
    public void Run_updates_are_monotonic()
    {
        var run = NewRun();
        Assert.True(run.Apply(new PipelineRunUpdate(RunStatus.InProgress, null, T0, null, T0.AddMinutes(1), null)));
        Assert.True(run.Apply(new PipelineRunUpdate(RunStatus.Completed, RunConclusion.Failure, T0, T0.AddMinutes(5), T0.AddMinutes(5), null)));
        Assert.False(run.Apply(new PipelineRunUpdate(RunStatus.InProgress, null, T0, null, T0.AddMinutes(2), null)));
        Assert.Equal(RunStatus.Completed, run.Status);
        Assert.True(run.IsFailed);
        Assert.Equal(300, run.DurationSeconds);
        Assert.False(run.Apply(new PipelineRunUpdate(RunStatus.Completed, RunConclusion.Failure, T0, T0.AddMinutes(5), T0.AddMinutes(5), null)));
    }

    [Fact]
    public void Deployment_ignores_older_status_events()
    {
        var deployment = new Deployment(Guid.NewGuid(), EventSource.Api, "d1", "production", "main", "abc", null, null, null, null, T0);
        Assert.True(deployment.IsProduction);
        Assert.True(deployment.ApplyStatus(DeploymentStatus.Success, "https://x.example", T0.AddMinutes(3)));
        Assert.False(deployment.ApplyStatus(DeploymentStatus.InProgress, null, T0.AddMinutes(1)));
        Assert.Equal(DeploymentStatus.Success, deployment.Status);
        Assert.Equal(180, deployment.DurationSeconds);
    }

    [Fact]
    public void Delivery_retries_back_off_and_stop()
    {
        var delivery = new WebhookDelivery(Guid.NewGuid(), Guid.NewGuid(), "d", "push", null, "{}", "h", T0);
        delivery.MarkFailed("boom", T0);
        Assert.Equal(T0.AddSeconds(30), delivery.NextAttemptAt);
        delivery.MarkFailed("boom", T0);
        Assert.Equal(T0.AddSeconds(120), delivery.NextAttemptAt);
        for (var i = 0; i < 3; i++)
        {
            delivery.MarkFailed("boom", T0);
        }

        Assert.Null(delivery.NextAttemptAt);
        delivery.PurgePayload();
        Assert.Throws<Domain.Common.DomainException>(() => delivery.RequeueManually(T0));
    }

    [Fact]
    public void Incident_recurrence_and_resolution()
    {
        var incident = new Domain.Incidents.Incident(Guid.NewGuid(), 1, "CI broken", Domain.Incidents.IncidentSeverity.High,
            Domain.Incidents.IncidentSource.PipelineFailure, "fp", null, null, null, null, T0);
        incident.ChangeStatus(Domain.Incidents.IncidentStatus.Mitigated, T0);
        incident.RecordOccurrence(T0.AddHours(1));
        Assert.Equal(Domain.Incidents.IncidentStatus.Investigating, incident.Status);
        Assert.Equal(2, incident.OccurrenceCount);
        incident.ChangeStatus(Domain.Incidents.IncidentStatus.Resolved, T0.AddHours(2));
        Assert.Null(incident.Fingerprint);
        Assert.Equal(T0.AddHours(2), incident.ResolvedAt);
    }

    [Theory]
    [InlineData("success", RunConclusion.Success)]
    [InlineData("timed_out", RunConclusion.TimedOut)]
    [InlineData("weird", RunConclusion.Unknown)]
    public void GitHub_conclusions_are_mapped(string value, RunConclusion expected) =>
        Assert.Equal(expected, GitHubEventProcessor.ParseConclusion(value));
}
